-- Tablas de infraestructura (patron Transactional Outbox + consumidor idempotente)
CREATE TABLE IF NOT EXISTS outbox_event (
    id uuid PRIMARY KEY,
    aggregate_type varchar(100) NOT NULL,
    aggregate_id varchar(100) NOT NULL,
    event_type varchar(150) NOT NULL,
    topic varchar(150) NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    attempts integer NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS ix_outbox_pending ON outbox_event (created_at) WHERE published_at IS NULL;

CREATE TABLE IF NOT EXISTS processed_event (
    event_id uuid PRIMARY KEY,
    consumer varchar(150) NOT NULL,
    processed_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX ix_cliente_proveedor_acti ON cliente_proveedor (esta_acti);
CREATE INDEX ix_cliente_proveedor_deno ON cliente_proveedor (denominacion) INCLUDE (codi_clie_prov);
CREATE INDEX ix_cliente_proveedor_esta_clie ON cliente_proveedor (esta_acti) INCLUDE (codi_clie_prov, razo_soci, ruc, denominacion, frecuencia);
CREATE INDEX ix_cliente_proveedor_razo_soci ON cliente_proveedor (razo_soci);
CREATE INDEX ix_ubigeo_provincia_fk_codi_ubi_reg_sunat ON ubigeo_provincia (codi_ubi_reg_sunat); -- indice de FK (mejora)
CREATE INDEX ix_ubigeo_distrito_fk_codi_ubi_prov_sunat ON ubigeo_distrito (codi_ubi_prov_sunat); -- indice de FK (mejora)

-- Las FK se crean NOT VALID porque en SQL Server estaban WITH NOCHECK.
-- Tras depurar datos: ALTER TABLE <t> VALIDATE CONSTRAINT <fk>;

ALTER TABLE valores_unitarios_anuales ADD CONSTRAINT fk_valores_unitarios_anuales_valores_unitarios FOREIGN KEY (codi_valo_unit) REFERENCES valores_unitarios (codi_valo_unit) NOT VALID;
ALTER TABLE ubigeo_provincia ADD CONSTRAINT fk_ubigeo_provincia_ubigeo_region FOREIGN KEY (codi_ubi_reg_sunat) REFERENCES ubigeo_region (codi_ubi_reg_sunat) NOT VALID;
ALTER TABLE ubigeo_distrito ADD CONSTRAINT fk_ubigeo_distrito_ubigeo_provincia FOREIGN KEY (codi_ubi_prov_sunat) REFERENCES ubigeo_provincia (codi_ubi_prov_sunat) NOT VALID;

