CREATE SCHEMA IF NOT EXISTS contabilidad;
SET search_path TO contabilidad;
-- Servicio: ms-contabilidad (Contabilidad, Activos y Libros SUNAT)
-- Tablas: 82

-- Movi_Contables
CREATE TABLE movi_contables (
    codi_contable varchar(10) NOT NULL,
    anio varchar(4),
    mes varchar(2),
    subdia varchar(1),
    compr varchar(10),
    codi_mone varchar(2),
    fecha timestamp(3),
    nro_cuen varchar(7),
    nro_sub_cuen varchar(7),
    codi_clie_prov varchar(5),
    serie varchar(5),
    nro_docu varchar(20),
    codi_tipo_docu varchar(4),
    importe numeric(18,2),
    igv numeric(18,2),
    otros numeric(18,2),
    total numeric(18,2),
    importe_d numeric(18,2),
    igv_d numeric(18,2),
    otros_d numeric(18,2),
    total_d numeric(18,2),
    registro varchar(10),
    codi_unid_oper varchar(5),
    glosa varchar(200),
    cargo_abono varchar(1),
    fecha_venc timestamp(3),
    tipo_cambio numeric(18,4),
    situ_cheq varchar(2),
    tipo_cambio_2 numeric(18,4),
    codi_vouc varchar(10),
    fecha_spot timestamp(3),
    num_spot varchar(10),
    codi_pers varchar(5),
    codi_sema varchar(10),
    codi_nota_ingr varchar(10),
    nro_orde_comp varchar(10),
    nro_orde_pedi varchar(10),
    codi_pres varchar(4),
    nro_presu varchar(5),
    banco varchar(7),
    cartera boolean DEFAULT false,
    hecho_por varchar(5),
    itf varchar(1),
    compensa boolean,
    detraccion boolean,
    fech_pago timestamp(3),
    ref varchar(5),
    nro_fact varchar(20),
    codi_memo bigint,
    tipo_movi varchar(2),
    codi_desti varchar(1),
    codi_tasa_detr varchar(5),
    retencion boolean,
    codi_ingr bigint,
    codi_alma varchar(2),
    codi_tipo_intan varchar(2),
    codi_aduana smallint,
    anio_dua_dsi smallint,
    nro_detrac varchar(10),
    fecha_detrac timestamp(0),
    fecha_nd_nc timestamp(0),
    tipo_docu_nd_nc varchar(4),
    serie_nd_nc varchar(5),
    nro_docu_nd_nc varchar(10),
    tipo_venta varchar(1),
    codi_libro_regi smallint,
    codi_tipo_medio_pago smallint,
    banco_aux varchar(2),
    fecha_creacion timestamp(3),
    estado_inic integer,
    creacion timestamp(3),
    id_flujo integer,
    id_tipo_flujo integer,
    codi_oper varchar(4),
    codi_bien_serv varchar(5),
    pdetr numeric(18,3),
    valor_refe numeric(18,2),
    placa varchar(100),
    nro_refe varchar(10),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_movi_contables PRIMARY KEY (codi_contable)
);

