CREATE SCHEMA IF NOT EXISTS finanzas;
SET search_path TO finanzas;
-- Servicio: ms-finanzas (Finanzas: Caja, Bancos y Letras)
-- Tablas: 45

-- CAJA_CHICA
CREATE TABLE caja_chica (
    codi_alma varchar(2) NOT NULL,
    nro_recibo varchar(10) NOT NULL,
    fecha timestamp(3),
    tipo_io integer NOT NULL,
    codi_mone varchar(2),
    codi_clie_prov varchar(5),
    glosa varchar(150),
    codi_tipo_docu varchar(4),
    serie varchar(10),
    nro_docu varchar(20),
    tipo_contab varchar(3),
    importe numeric(18,3),
    codi_usua_soli varchar(5),
    prov_canc varchar(1),
    hora_real timestamp(3),
    codi_unid_oper varchar(5),
    placa_carreta varchar(5),
    rendir varchar(1),
    nro_recibo_aux varchar(10),
    codi_liqu bigint,
    importe_s numeric(18,3),
    ruta_de varchar(200),
    ruta_a varchar(200),
    fecha_docu timestamp(3),
    placa varchar(5),
    galones numeric(18,2),
    km_ini numeric(18,2),
    km_fin numeric(18,2),
    fecha_vence timestamp(3),
    dscto_adm varchar(1),
    hecho_por varchar(5),
    estado varchar(1),
    activo varchar(1),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_caja_chica PRIMARY KEY (codi_alma, nro_recibo, tipo_io)
);

-- LETRAS_PRODUCTOS
