-- =====================================================================
-- ESQUEMA produccion
-- =====================================================================
CREATE SCHEMA IF NOT EXISTS produccion;
SET search_path TO produccion;
-- Servicio: ms-produccion (Pesca, Flota y Produccion)
-- Tablas: 40

-- Analisis_Aceite
CREATE TABLE analisis_aceite (
    cod_analisis bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    codi_ingr bigint NOT NULL,
    codi_alma varchar(2) NOT NULL,
    item integer NOT NULL,
    codi_prod varchar(8) NOT NULL,
    i_o varchar(1) NOT NULL,
    condicion smallint NOT NULL,
    fecha_analisis timestamp(3),
    fecha_registro timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    codi_usua varchar(5),
    estado_ingreso smallint,
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_analisis_aceite PRIMARY KEY (cod_analisis),
    CONSTRAINT uq_analisis_aceite_ix_analisis_aceite UNIQUE (codi_ingr, codi_alma, item, codi_prod)
);

-- LUGAR_ORIGEN
CREATE TABLE lugar_origen (
    codi_luga varchar(3) NOT NULL,
    desc_luga varchar(200),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_lugar_origen PRIMARY KEY (codi_luga)
);

-- INFORME_ACIDEZ
CREATE TABLE informe_acidez (
    codi_alma varchar(2) NOT NULL,
    fecha varchar(10) NOT NULL,
    peso numeric(18,2),
    superior numeric(18,2),
    medio numeric(18,2),
    compo numeric(18,2),
    fondo numeric(18,2),
    solidos numeric(18,2),
    altura numeric(18,2),
    observaciones varchar(100),
    hora varchar(10),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_informe_acidez PRIMARY KEY (codi_alma, fecha)
);

-- NroTrip_Embar
CREATE TABLE nrotrip_embar (
    codi_unid_oper varchar(5) NOT NULL,
    nro_trip integer NOT NULL,
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_nrotrip_embar PRIMARY KEY (codi_unid_oper)
);

-- Nota_ingreso_Aceite
CREATE TABLE nota_ingreso_aceite (
    codi_ingr bigint NOT NULL,
    codi_alma varchar(2) NOT NULL,
    nro_ingr bigint,
    fecha timestamp(3),
    codi_mone varchar(2),
    codi_tipo_docu varchar(4),
    serie varchar(3),
    numero varchar(10),
    codi_clie_prov varchar(5),
    codi_moti_tras varchar(2),
    tpc numeric(18,4),
    observacion varchar(250),
    codi_orde bigint,
    rela_vale bigint,
    anulado varchar(1),
    subt numeric(18,2),
    igv numeric(18,2),
    total numeric(18,2),
    orden_compra bigint,
    productor varchar(5),
    transporte varchar(5),
    placa varchar(10),
    codi_doc varchar(4),
    serfact varchar(5),
    nrofact varchar(10),
    fecha_fact timestamp(0),
    codi_sali bigint,
    chofer varchar(4),
    periodo varchar(4),
    indice_rela bigint,
    procedencia varchar(3),
    contabilizado boolean NOT NULL DEFAULT false,
    codi_unid_oper_prod varchar(5),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_nota_ingreso_aceite PRIMARY KEY (codi_ingr, codi_alma)
);

-- POZAS
CREATE TABLE pozas (
    codi_poza varchar(2) NOT NULL,
    desc_poza varchar(50) NOT NULL,
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_pozas PRIMARY KEY (codi_poza)
);

-- TIPO_DESTINO
CREATE TABLE tipo_destino (
    codi_tipo_dest varchar(2) NOT NULL,
    desc_tipo_dest varchar(100),
    nemo varchar(4),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_tipo_destino PRIMARY KEY (codi_tipo_dest)
);

