-- ORDEN_COMPRA_ACEITE
CREATE TABLE orden_compra_aceite (
    codi_orde bigint NOT NULL,
    nro_orde bigint,
    codi_alma varchar(2),
    fecha timestamp(3),
    codi_mone varchar(2),
    codi_tipo_docu varchar(4),
    serie varchar(3),
    numero varchar(10),
    codi_clie_prov varchar(5),
    codi_moti_tras varchar(2),
    tpc numeric(18,4),
    observacion varchar(250),
    codi_alma_dest varchar(2),
    contabilizado varchar(1),
    codi_vouc varchar(10),
    subt numeric(18,2),
    igv numeric(18,2),
    total numeric(18,2),
    productor varchar(5),
    transporte varchar(5),
    placa varchar(10),
    serfact varchar(5),
    nrofact varchar(10),
    codi_doc varchar(4),
    periodo varchar(4),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_orden_compra_aceite PRIMARY KEY (codi_orde)
);

-- SITU_EMBA
CREATE TABLE situ_emba (
    codi_situ varchar(2) NOT NULL,
