-- DERECHOPESCA
CREATE TABLE derechopesca (
    mesanio varchar(6) NOT NULL,
    codi_unid_oper varchar(5) NOT NULL,
    captura numeric(12,3),
    factor numeric(12,3),
    derecho numeric(12,3),
    porcentaje numeric(12,3),
    derechopor numeric(12,3),
    credito numeric(12,3),
    deducion numeric(12,3),
    total numeric(12,3),
    aplicar varchar(1),
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_derechopesca PRIMARY KEY (mesanio, codi_unid_oper)
);

-- TANQUES
