COMMENT ON TABLE puerto IS 'Legado: dbo.Puerto';
COMMENT ON TABLE tipos_orden_produccion IS 'Legado: dbo.TIPOS_ORDEN_PRODUCCION';
COMMENT ON TABLE tipo_titu_pesc IS 'Legado: dbo.TIPO_TITU_PESC';
COMMENT ON TABLE destinos_pesca IS 'Legado: dbo.DESTINOS_PESCA';
COMMENT ON TABLE derechopesca IS 'Legado: dbo.DERECHOPESCA';
