    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_pbcatcol PRIMARY KEY (id)
);

-- Paper  (sin PK en el legado: se agrega clave sustituta)
CREATE TABLE paper (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    codi varchar(2) NOT NULL,
    descrip varchar(70) NOT NULL,
    audit_created_at timestamptz NOT NULL DEFAULT now(),
    audit_updated_at timestamptz,
    audit_user varchar(60),
    row_version bigint NOT NULL DEFAULT 0,
    CONSTRAINT pk_paper PRIMARY KEY (id)
);

-- Tablas de infraestructura (patron Transactional Outbox + consumidor idempotente)
CREATE TABLE IF NOT EXISTS outbox_event (
    id uuid PRIMARY KEY,
    aggregate_type varchar(100) NOT NULL,
    aggregate_id varchar(100) NOT NULL,
    event_type varchar(150) NOT NULL,
    topic varchar(150) NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    attempts integer NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS ix_outbox_pending ON outbox_event (created_at) WHERE published_at IS NULL;

CREATE TABLE IF NOT EXISTS processed_event (
    event_id uuid PRIMARY KEY,
    consumer varchar(150) NOT NULL,
    processed_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX ix_pbcatvld_pbcatvld_idx ON pbcatvld (pbv_name);
CREATE UNIQUE INDEX ix_pbcattbl_pbcattbl_idx ON pbcattbl (pbt_tnam, pbt_ownr);
CREATE UNIQUE INDEX ix_pbcatfmt_pbcatfmt_idx ON pbcatfmt (pbf_name);
CREATE UNIQUE INDEX ix_pbcatedt_pbcatedt_idx ON pbcatedt (pbe_name, pbe_seqn);
CREATE UNIQUE INDEX ix_pbcatcol_pbcatcol_idx ON pbcatcol (pbc_tnam, pbc_ownr, pbc_cnam);

